-- 2026-10-24 사용자 요청: 가상 인물 200명에게 회사 메일(성을 뺀 이름+성 @solideos.com)을 준다.
-- 명부 표의 속성일 뿐 Auth 계정·로그인과 연결하지 않는다(ADR-019). 실제 발송 대상이 아니다.
alter table public.team_members add column if not exists email text;

alter table public.team_members
  drop constraint if exists team_members_email_format,
  drop constraint if exists team_members_org_email_key;
alter table public.team_members
  add constraint team_members_email_format check (
    email is null or (email = lower(email) and email ~ '^[a-z0-9]+@[a-z0-9-]+(\.[a-z0-9-]+)+$')
  ),
  add constraint team_members_org_email_key unique (org_id, email);

