begin
  if not exists (select 1 from public.organizations o where o.id = demo_org and o.slug = 'org-01' and o.is_demo) then
    return;
  end if;
  update public.team_members m set email = p.email
  from jsonb_to_recordset(emails) as p(person_code text, name text, email text)
  where m.org_id = demo_org and m.is_demo and m.person_code = p.person_code and m.name = p.name;
  -- 이미 있는 데모 직원 중 이름이 달라 못 채운 사람이 있으면 덮지 않고 실패시킨다.
  if exists (
    select 1 from public.team_members m
    join jsonb_to_recordset(emails) as p(person_code text, name text, email text)
      on p.person_code = m.person_code
    where m.org_id = demo_org and m.is_demo and m.email is distinct from p.email
  ) then
    raise exception 'people_email_backfill_mismatch';
  end if;
end;
$$;

comment on column public.team_members.email is 'Company mailbox shown in the roster; synthetic for demo people and never linked to Auth.';
